class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return f'{self.name}在叫'

class Dog(Animal):
    def __init__(self, name):
        # ❌ 少了一行：父类的属性没有初始化
        pass

name = input()
d = Dog(name)
print(d.speak())

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return '……'

class Dog(Animal):
    # 补全：重写 speak，返回 '汪汪'
    pass

class Cat(Animal):
    # 补全：重写 speak，返回 '喵喵'
    pass

def zoo(animal):
    print(f'{animal.name}说{animal.speak()}')

name = input()
zoo(Dog(name))
zoo(Cat('咪咪'))

