class MagicalCreature:
    def __init__(self, name, power):
        self.name = name
        self.__power = power          # 私有属性：魔法威力（封装）

    def get_power(self):              # 受控读取口
        return self.__power

    def attack(self):
        return f'{self.name}施放普通攻击，威力 {self.get_power()}'

class FireDragon(MagicalCreature):
    # 补全 __init__：接收 name, power, element；
    # 用 super().__init__(name, power) 把公共属性交给父类，再保存 self.element
    def __init__(self, name, power, element):
        pass

    # 补全 attack：返回 f'{self.name}喷出{self.element}火焰，威力 {self.get_power()}'
    def attack(self):
        pass

class IceBeast(MagicalCreature):
    # 补全 __init__：接收 name, power, element；同上
    def __init__(self, name, power, element):
        pass

    # 补全 attack：返回 f'{self.name}释放{self.element}冰霜，威力 {self.get_power()}'
    def attack(self):
        pass

name = input()
element = input()
print(FireDragon(name, 80, element).attack())
print(IceBeast('冰晶兽', 60, '深蓝').attack())
